def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    if not cells:
        return out

    bottom = max(r for r, c in cells)
    for r, row in enumerate(out):
        for c, v in enumerate(row):
            if v == 6:
                out[r][c] = 0

    for r, c in cells:
        reflected_r = 2 * bottom + 1 - r
        if 0 <= reflected_r < len(out):
            out[reflected_r][c] = 4
    return out
